pub fn inversions(xs: &[i64]) -> i64 {
    let mut count = 0;
    for i in 0..xs.len() {
        let x = xs[i];
        for j in i + 1..xs.len() {
            if xs[j] <= x {
                count += 1;
            }
        }
    }
    count
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_inversions() {
        assert_eq!(inversions(&[3, 1, 2]), 2);
        assert_eq!(inversions(&[2, 2, 1]), 2);
        assert_eq!(inversions(&[5, 4, 3, 2, 1]), 10);
        assert_eq!(inversions(&[]), 0);
    }
}
